        far_alphas = []
        for rq in [2.2, 3.0, 4.0, 5.0, 6.0]:
            pl = interp_chain(left_chain, rq)
            pr = interp_chain(right_chain, rq)
            if pl and pr:
                sm = 0.5 * (pl[0] + pr[0])
                lm = 0.5 * (pl[1] + pr[1])
            elif pl:
                sm = pl[0] + 2.05 * pl[3]
                lm = pl[1] - 2.05 * pl[2]
            elif pr:
                sm = pr[0] - 2.05 * pr[3]
                lm = pr[1] + 2.05 * pr[2]
            else:
                continue
            alpha_deg = math.degrees(math.atan2(lm, max(0.5, sm)))
            if rq <= 3.2:
                near_alphas.append(alpha_deg)
            else:
                far_alphas.append(alpha_deg)

        if near_alphas or far_alphas:
            a_near = sum(near_alphas) / len(near_alphas) if near_alphas else 0.0
            a_far = sum(far_alphas) / len(far_alphas) if far_alphas else a_near
            raw_target_hitch = 0.8 * a_near + 1.35 * a_far

        # Near-wall lateral clearance guard
        right_near = [p[1] for p in right_chain if 0.3 <= p[0] <= 2.8]
        if right_near:
            closest_r = max(right_near)
            if closest_r > -1.50:
                raw_target_hitch += 16.0 * (closest_r - (-1.50))
        left_near = [p[1] for p in left_chain if 0.3 <= p[0] <= 2.8]
        if left_near:
            closest_l = min(left_near)
            if closest_l < 1.50:
                raw_target_hitch += 16.0 * (closest_l - 1.50)

        raw_target_hitch = max(-32.0, min(32.0, raw_target_hitch))
        state['filtered_target_hitch'] = 0.6 * state['filtered_target_hitch'] + 0.4 * raw_target_hitch

        if t - state['last_log_t'] >= 1.5:
            state['last_log_t'] = t
            print(f"t={t:.1f} rem={obs['progress']['remaining']:.1f} hitch={hitch_deg:.1f} tgt_h={state['filtered_target_hitch']:.1f} L={len(left_chain)} R={len(right_chain)} corners={len(cam.get('target_corners', []))}")

    target_hitch_deg = state['filtered_target_hitch']

    # Nonlinear hitch-angle tracking controller
    phi = math.radians(hitch_deg)
    phi_des = math.radians(target_hitch_deg)
    k_phi = 1.2
    rhs = (math.sin(phi) / L_TRAILER) - k_phi * (phi_des - phi)
    denom = (1.0 / L_WB) * (1.0 + (L_HITCH / L_TRAILER) * math.cos(phi))
    cmd_steer_deg = math.degrees(math.atan(rhs / denom))
    cmd_steer_deg = max(-34.0, min(34.0, cmd_steer_deg))

    turn_mag = max(abs(hitch_deg), abs(target_hitch_deg))
    if turn_mag > 18.0:
        speed = -1.15
    elif turn_mag > 8.0:
        speed = -1.35
    else:
        speed = -1.6

    return (cmd_steer_deg, speed, look_deg)

