import math

L_WB = 2.75
L_HITCH = 1.05
L_TRAILER = 2.60

state = {
    'last_log_t': -10.0,
    'filtered_target_hitch': None,
}

def interp_chain(chain, rq):
    if not chain:
        return None
    if rq < chain[0][2] - 0.5 or rq > chain[-1][2] + 0.5:
        return None
    if rq <= chain[0][2]:
        idx = 0
        s, l, _ = chain[0]
    elif rq >= chain[-1][2]:
        idx = len(chain) - 2
        s, l, _ = chain[-1]
    else:
        idx = 0
        s, l = chain[0][0], chain[0][1]
        for i in range(len(chain) - 1):
            r1, r2 = chain[i][2], chain[i+1][2]
            if r1 <= rq <= r2 or r2 <= rq <= r1:
                idx = i
                denom = (r2 - r1) if abs(r2 - r1) > 1e-4 else 1e-4
                w = max(0.0, min(1.0, (rq - r1) / denom))
                s = chain[i][0] + w * (chain[i+1][0] - chain[i][0])
                l = chain[i][1] + w * (chain[i+1][1] - chain[i][1])
                break
    i0 = max(0, idx)
    i1 = min(len(chain) - 1, idx + 1)
    if i1 == i0 and len(chain) > 1:
        i0 = max(0, i1 - 1)
    ds = chain[i1][0] - chain[i0][0]
    dl = chain[i1][1] - chain[i0][1]
    norm = math.hypot(ds, dl)
    if norm < 1e-4:
        ts, tl = 1.0, 0.0
    else:
        ts, tl = ds / norm, dl / norm
    return (s, l, ts, tl)

def analyze_bay_corners(corners_sl):
    if len(corners_sl) < 2:
        return None
    pts = sorted(corners_sl, key=lambda p: p[0])
    pairs = []
    used = set()
    for i in range(len(pts)):
        if i in used:
            continue
        for j in range(i + 1, len(pts)):
            if j in used:
                continue
            if abs(pts[i][0] - pts[j][0]) < 1.8 and abs(pts[i][1] - pts[j][1]) >= 1.2:
                p_left = pts[i] if pts[i][1] > pts[j][1] else pts[j]
                p_right = pts[j] if pts[i][1] > pts[j][1] else pts[i]
                sm = 0.5 * (p_left[0] + p_right[0])
                lm = 0.5 * (p_left[1] + p_right[1])
                pairs.append((sm, lm, p_left, p_right))
                used.add(i)
                used.add(j)
                break
    if not pairs:
        return None
    # Longitudinal angle from side edges if >= 3 corners
    psi_list = []
    left_pts = [p for p in pts if p[1] > 0]
    right_pts = [p for p in pts if p[1] <= 0]
    if len( pairs ) >= 2:
        p0, p1 = pairs[0], pairs[-1]
        for a, b in [(p0[2], p1[2]), (p0[3], p1[3]), ((p0[0], p0[1]), (p1[0], p1[1]))]:
            ds = b[0] - a[0]
            dl = b[1] - a[1]
            if ds > 1.5:
                psi_list.append(math.degrees(math.atan2(dl, ds)))
    else:
        p0 = pairs[0]
        for p in pts:
            if p is not p0[2] and p is not p0[3]:
                ref = p0[2] if abs(p[1] - p0[2][1]) < abs(p[1] - p0[3][1]) else p0[3]
                ds = p[0] - ref[0]
                dl = p[1] - ref[1]
                if abs(ds) > 1.5:
                    if ds < 0:
                        ds, dl = -ds, -dl
                    psi_list.append(math.degrees(math.atan2(dl, ds)))
    sm_avg = sum(p[0] for p in pairs) / len(pairs)
    lm_avg = sum(p[1] for p in pairs) / len(pairs)
    psi_deg = sum(psi_list) / len(psi_list) if psi_list else None
    return (sm_avg, lm_avg, psi_deg)

def control(obs):
    t = obs['t']
    hitch_deg = obs['hitch_deg']
    rem = obs['progress']['remaining']
    if state['filtered_target_hitch'] is None:
        state['filtered_target_hitch'] = hitch_deg

    look_deg = obs['rig'].get('screen_gaze_deg', -23.0)
    if look_deg is None:
        look_deg = -23.0

    gamma = math.radians(obs['rig']['trailer_heading_deg'])
    u_rev_x, u_rev_y = -math.cos(gamma), -math.sin(gamma)
    u_lat_x, u_lat_y = -math.sin(gamma), math.cos(gamma)
    tx, ty = obs['rig']['trailer_rear']

    cam = obs.get('views', {}).get('camera')
    raw_target_hitch = state['filtered_target_hitch']

    if cam and cam.get('walls'):
        ox, oy = cam['origin']
        pts = []
        for b_deg, dist in cam['walls']:
            b_rad = math.radians(b_deg)
            px = ox + dist * math.cos(b_rad)
            py = oy + dist * math.sin(b_rad)
            dx, dy = px - tx, py - ty
            s = dx * u_rev_x + dy * u_rev_y
            l = dx * u_lat_x + dy * u_lat_y
            r = math.hypot(s, l)
            pts.append((s, l, r))

        chains = []
        cur = []
        for p in pts:
            if cur:
                prev = cur[-1]
                if math.hypot(p[0] - prev[0], p[1] - prev[1]) > 2.2 or p[2] < prev[2] - 1.5:
                    chains.append(cur)
                    cur = [p]
                else:
                    cur.append(p)
            else:
                cur.append(p)
        if cur:
            chains.append(cur)

        left_chain = []
        right_chain = []
        for c in chains:
            if len(c) >= 2:
                if c[0][1] > 0.0:
                    if len(c) > len(left_chain):
                        left_chain = c
                else:
                    if len(c) > len(right_chain):
                        right_chain = c

        near_alphas = []
        far_alphas = []
        for rq in [2.2, 3.0, 4.0, 5.0, 6.0, 7.0]:
            pl = interp_chain(left_chain, rq)
            pr = interp_chain(right_chain, rq)
            if pl and pr:
                sm = 0.5 * (pl[0] + pr[0])
                lm = 0.5 * (pl[1] + pr[1])
            elif pl:
                sm = pl[0] + 2.05 * pl[3]
                lm = pl[1] - 2.05 * pl[2]
            elif pr:
                sm = pr[0] - 2.05 * pr[3]
                lm = pr[1] + 2.05 * pr[2]
            else:
                continue
            alpha_deg = math.degrees(math.atan2(lm, max(0.5, sm)))
            if rq <= 3.2:
                near_alphas.append(alpha_deg)
            else:
                far_alphas.append(alpha_deg)

        a_near = sum(near_alphas) / len(near_alphas) if near_alphas else 0.0
        a_far = sum(far_alphas) / len(far_alphas) if far_alphas else a_near
        if near_alphas or far_alphas:
            raw_target_hitch = 0.8 * a_near + 1.35 * a_far

        # Bay corners processing
        corners_sl = []
        for b_deg, dist in cam.get('target_corners', []):
            b_rad = math.radians(b_deg)
            px = ox + dist * math.cos(b_rad)
            py = oy + dist * math.sin(b_rad)
            dx, dy = px - tx, py - ty
            s = dx * u_rev_x + dy * u_rev_y
            l = dx * u_lat_x + dy * u_lat_y
            corners_sl.append((round(s, 2), round(l, 2)))

        bay_info = analyze_bay_corners(corners_sl)
        if bay_info is not None and rem < 10.0:
            sm_b, lm_b, psi_b = bay_info
            alpha_b = math.degrees(math.atan2(lm_b, max(1.2, sm_b)))
            heading_ref = psi_b if psi_b is not None else a_far
            if rem < 2.2:
                bay_hitch = 0.6 * alpha_b + 1.0 * heading_ref
            else:
                bay_hitch = 1.3 * alpha_b + 0.9 * heading_ref
            raw_target_hitch = 0.35 * raw_target_hitch + 0.65 * bay_hitch

        # Near-wall lateral clearance guard for trailer
        right_near = [p[1] for p in right_chain if 0.3 <= p[0] <= 2.8]
        if right_near:
            closest_r = max(right_near)
            if closest_r > -1.45:
                raw_target_hitch += 16.0 * (closest_r - (-1.45))
        left_near = [p[1] for p in left_chain if 0.3 <= p[0] <= 2.8]
        if left_near:
            closest_l = min(left_near)
            if closest_l < 1.45:
                raw_target_hitch += 16.0 * (closest_l - 1.45)

        max_h = 20.0 if rem < 7.0 else 28.0
        raw_target_hitch = max(-max_h, min(max_h, raw_target_hitch))
        state['filtered_target_hitch'] = 0.55 * state['filtered_target_hitch'] + 0.45 * raw_target_hitch

        if t - state['last_log_t'] >= 1.5:
            state['last_log_t'] = t
            print(f"t={t:.1f} rem={rem:.1f} hitch={hitch_deg:.1f} tgt_h={state['filtered_target_hitch']:.1f} L={len(left_chain)} R={len(right_chain)} c={corners_sl}")

    target_hitch_deg = state['filtered_target_hitch']

    # Nonlinear hitch-angle tracking controller
    phi = math.radians(hitch_deg)
    phi_des = math.radians(target_hitch_deg)
    k_phi = 1.25
    rhs = (math.sin(phi) / L_TRAILER) - k_phi * (phi_des - phi)
    denom = (1.0 / L_WB) * (1.0 + (L_HITCH / L_TRAILER) * math.cos(phi))
    cmd_steer_deg = math.degrees(math.atan(rhs / denom))
    cmd_steer_deg = max(-34.0, min(34.0, cmd_steer_deg))

    turn_mag = max(abs(hitch_deg), abs(target_hitch_deg))
    if turn_mag > 18.0:
        speed = -1.15
    elif turn_mag > 8.0:
        speed = -1.35
    else:
        speed = -1.55

    return (cmd_steer_deg, speed, look_deg)

