import math

woke = False
mode = 'pull_fwd'

def control(obs):
    global woke, mode
    hitch = obs['hitch_deg']
    look = -40.8

    # Check front clearance from direct/periphery views
    min_front_x = 99.0
    for vname in ('direct', 'periphery'):
        vdata = obs.get('views', {}).get(vname)
        if vdata and vdata.get('walls'):
            ox, oy = vdata['origin']
            for brg, dist in vdata['walls']:
                b = math.radians(brg)
                vx = ox + dist * math.cos(b)
                vy = oy + dist * math.sin(b)
                if vx > 4.5 and abs(vy) < 1.65:
                    if vx < min_front_x:
                        min_front_x = vx

    if mode == 'pull_fwd':
        if hitch >= -3.0 or min_front_x < 6.2:
            mode = 'rev'
            print(f'SWITCH TO REV: hitch={hitch:.1f}, min_front_x={min_front_x:.2f}, cov={obs["progress"]["covered"]:.2f}')
        else:
            if hitch < -14.0:
                steer = 42.0
                spd = 2.2
            else:
                steer = max(0.0, min(42.0, -3.0 * hitch))
                spd = 1.4
            return steer, spd, look

    if not woke:
        woke = True
        wake(f'straightened: hitch={hitch:.1f}, min_front_x={min_front_x:.2f}')

    # Safe gentle reverse holding current trailer angle
    steer = max(-42.0, min(42.0, 2.5 * hitch))
    return steer, -1.3, look

